def star(M, D, n_iters):
    Mn = M
    for n in range(1, n_iters + 1):
        keep = []
        for x, y in D:
            r, y_hat = Mn.generate(x)
            if y_hat == y:
                keep.append((x, r, y))
            else:
                r2, y2 = Mn.generate(add_hint(x, y))
                if y2 == y:
                    keep.append((x, r2, y))
        Mn = finetune(M, keep)
    return Mn
